import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"19、【临】 兑下坤上","description":"温公易说 - 19、【临】 兑下坤上","frontmatter":{"title":"19、【临】 兑下坤上","description":"温公易说 - 19、【临】 兑下坤上"},"headers":[],"relativePath":"zh/classics/wengong/020.md","filePath":"zh/classics/wengong/020.md"}'),n={name:"zh/classics/wengong/020.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_19、【临】-兑下坤上" tabindex="-1">19、【临】 兑下坤上 <a class="header-anchor" href="#_19、【临】-兑下坤上" aria-label="Permalink to “19、【临】 兑下坤上”">​</a></h1><h3 id="彖曰-临-刚浸而长-说而顺-刚中而应-大亨以正-天之道也。至于八月有凶-消不久也。" tabindex="-1">彖曰：临，刚浸而长，说而顺，刚中而应，大亨以正，天之道也。至于八月有凶，消不久也。 <a class="header-anchor" href="#彖曰-临-刚浸而长-说而顺-刚中而应-大亨以正-天之道也。至于八月有凶-消不久也。" aria-label="Permalink to “彖曰：临，刚浸而长，说而顺，刚中而应，大亨以正，天之道也。至于八月有凶，消不久也。”">​</a></h3><p>八月者，周之八月也。阳生于复，长于临，阴生于姤，长于遁。遁与临反者也。圣人防微杜渐，故于阳长之初，而着阴之戒也。</p><h3 id="象曰-泽上有地-临。君子以教思无穷-容保民无疆。" tabindex="-1">象曰：泽上有地，临。君子以教思无穷，容保民无疆。 <a class="header-anchor" href="#象曰-泽上有地-临。君子以教思无穷-容保民无疆。" aria-label="Permalink to “象曰：泽上有地，临。君子以教思无穷，容保民无疆。”">​</a></h3><p>教思无穷，容保民无疆，功之所以大也。</p><h3 id="初九-咸临-贞吉-象曰-咸临-贞吉-志行正也。" tabindex="-1">初九：咸临，贞吉 象曰：咸临，贞吉，志行正也。 <a class="header-anchor" href="#初九-咸临-贞吉-象曰-咸临-贞吉-志行正也。" aria-label="Permalink to “初九：咸临，贞吉 象曰：咸临，贞吉，志行正也。”">​</a></h3><p>君子之所以能自大者，学于道也。学充于内，则志气夷怿矣。浸长于外，则人化而顺之矣。人化而顺之所以大也，有应于外，化顺之象也。夫道以正心为本，初九所以能感物而大，志行正也。孔子曰：学而时习之，不亦悦乎？有朋自远方来，不亦乐乎？传曰：大学之本，心正然后身修。</p><h3 id="九二-咸临-吉-无不利-象曰-咸临-吉无不利-未顺命也。" tabindex="-1">九二：咸临，吉，无不利 象曰：咸临，吉无不利，未顺命也。 <a class="header-anchor" href="#九二-咸临-吉-无不利-象曰-咸临-吉无不利-未顺命也。" aria-label="Permalink to “九二：咸临，吉，无不利 象曰：咸临，吉无不利，未顺命也。”">​</a></h3><p>二在下体而不当位，故小人未肯尽受命也。</p><h3 id="六三-甘临-无攸利-既忧之-无咎-象曰-甘临-位不当也。既忧之-咎不长也。" tabindex="-1">六三：甘临，无攸利，既忧之，无咎 象曰：甘临，位不当也。既忧之，咎不长也。 <a class="header-anchor" href="#六三-甘临-无攸利-既忧之-无咎-象曰-甘临-位不当也。既忧之-咎不长也。" aria-label="Permalink to “六三：甘临，无攸利，既忧之，无咎 象曰：甘临，位不当也。既忧之，咎不长也。”">​</a></h3><h3 id="六四-至临-无咎-象曰-至临-无咎-位当也。" tabindex="-1">六四：至临，无咎 象曰：至临，无咎，位当也。 <a class="header-anchor" href="#六四-至临-无咎-象曰-至临-无咎-位当也。" aria-label="Permalink to “六四：至临，无咎 象曰：至临，无咎，位当也。”">​</a></h3><p>进升上体，至大之境，已得其位，故无咎也。</p><h3 id="六五-知临-大君之宜-吉-象曰-大君之宜-行中之谓也。" tabindex="-1">六五：知临，大君之宜，吉 象曰：大君之宜，行中之谓也。 <a class="header-anchor" href="#六五-知临-大君之宜-吉-象曰-大君之宜-行中之谓也。" aria-label="Permalink to “六五：知临，大君之宜，吉 象曰：大君之宜，行中之谓也。”">​</a></h3><h3 id="上六-敦临-吉-无咎-象曰-敦临之吉-志在内也。" tabindex="-1">上六：敦临，吉，无咎 象曰：敦临之吉，志在内也。 <a class="header-anchor" href="#上六-敦临-吉-无咎-象曰-敦临之吉-志在内也。" aria-label="Permalink to “上六：敦临，吉，无咎 象曰：敦临之吉，志在内也。”">​</a></h3>',14)])])}const b=e(n,[["render",l]]);export{p as __pageData,b as default};
